function getFastSupersetPair(dayName, exName) {
  var pairs = FAST_MODE_SUPERSETS[dayName] || [];
  for (var i = 0; i < pairs.length; i++) {
    var pair = pairs[i];
    if (sameExerciseName(pair.a, exName)) return { pair: pair, role: "a", partner: pair.b };
    if (sameExerciseName(pair.b, exName)) return { pair: pair, role: "b", partner: pair.a };
  }
  return null;
}

function getSupersetBlockForExercise(dayName, exName) {
  var info = getFastSupersetPair(dayName, exName);
  if (!info) return null;
  return {
    title: displayExerciseName(info.pair.a) + " + " + displayExerciseName(info.pair.b),
    rest: info.pair.rest || 0,
    role: info.role,
    partner: displayExerciseName(info.partner)
  };
}

