              var ex = getExForMonth(mergedEx);
              var db = EX[ex.n];
              var isX = openEx === i;
              var tLog = getLog(ex.n, dayIdx);
              var noteDraftKey = getExerciseNoteDraftKey(ex.n, dayIdx);
