              var hasV = month > 1 && rawEx["v" + month];
              var flowSupersetMeta = isDaySupersetActive ? getSupersetBlockForExercise(dayData && dayData.name, ex.n) : null;
              var baseRestSec = getExerciseRestSeconds(rawEx, ex);
